Task_UpdateBgDotsPalette.body:
u16 sp8[2];
    s16 *data = gTasks[taskId].data;
    const u16 *pal1 = (const u16 *)GetWordTaskArg(taskId, 1);
    const u16 *pal2 = (const u16 *)GetWordTaskArg(taskId, 3);

